input.command:
node <<'EOF'
const fs = require('fs');
const path = require('path');
const files = [];
function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (/\.(js|mjs|cjs|ts)$/.test(e.name)) files.push(p);
  }
}
walk('src'); walk('test');
let renamed = 0, bumped = 0, changed = 0;
for (const f of files) {
  const orig = fs.readFileSync(f, 'utf8');
  renamed += (orig.match(/\bretryPolicy\b/g) || []).length;
  bumped += (orig.match(/\bmaxAttempts: 3\b/g) || []).length;
  const next = orig.replace(/\bretryPolicy\b/g, 'backoffPolicy').replace(/\bmaxAttempts: 3\b/g, 'maxAttempts: 5');
  if (next !== orig) { fs.writeFileSync(f, next); changed++; }
}
console.log(`files scanned: ${files.length}, files changed: ${changed}, identifiers renamed: ${renamed}, maxAttempts bumped: ${bumped}`);
EOF
echo "--- leftover check:"; grep -rn "retryPolicy\|maxAttempts: 3" src test || echo "none"; echo "--- git diff stat:"; git diff --stat

